<?php $errors=flash_errors();$success=flash_message(); ?>
<div class="card"><h1><?= e($pageTitle) ?></h1><p>Activez une prestation dans une ou plusieurs villes. Chaque combinaison produit une page unique, rédigée manuellement ou générée par l’IA.</p><?php if($success): ?><div class="alert success"><?= e($success) ?></div><?php endif; ?><?php if(!empty($errors['form'])): ?><div class="alert error"><?= e($errors['form']) ?></div><?php endif; ?></div>

<div class="card"><h2>Activer des combinaisons</h2><form method="post" action="/admin/local-pages"><?= csrf_field() ?><div class="row"><div><label>Service</label><select name="company_service_id" required><option value="">Choisir</option><?php foreach($services as $service): ?><option value="<?= (int)$service->id() ?>"><?= e($service->getAttribute('public_name')) ?></option><?php endforeach; ?></select></div><div><label>Mode de contenu</label><select name="content_mode"><option value="ai">Génération IA</option><option value="manual">Contenu manuel / JSON</option></select></div><div><label>Publication après génération</label><select name="status"><option value="draft">Brouillon</option><option value="published">Publier</option></select></div></div><label>Villes</label><div class="local-city-grid"><?php foreach($cities as $city): ?><label><input type="checkbox" name="city_ids[]" value="<?= (int)$city['id'] ?>"> <?= e($city['name']) ?> <small><?= e($city['postal_code']) ?></small></label><?php endforeach; ?></div><button type="submit">Activer les pages</button></form></div>

<div class="card"><h2>Import JSON en cascade</h2><p>Le service accepte son identifiant ou son slug. La ville accepte son identifiant, son code INSEE, son slug ou son nom. Seules les villes activées dans « Zones d’intervention » sont acceptées.</p><textarea id="local-json" rows="14" spellcheck="false">{
  "pages": [
    {
      "service": "nom-du-service",
